export function translateTextToHindi(rawText) {
  if (!rawText) return rawText;
  const normalized = rawText.replace(/\s+/g, ' ').trim();
  if (!normalized) return rawText;

  if (HI_EXACT_MAP[normalized]) {
    // Preserve leading/trailing whitespace if present
    const leadingMatch = rawText.match(/^\s*/);
    const trailingMatch = rawText.match(/\s*$/);
    const leading = leadingMatch ? leadingMatch[0] : '';
    const trailing = trailingMatch ? trailingMatch[0] : '';
    return `${leading}${HI_EXACT_MAP[normalized]}${trailing}`;
  }

  return rawText;
}

